const express=require('express'),fs=require('fs'),path=require('path'),crypto=require('crypto'),multer=require('multer'),cron=require('node-cron'),initSql=require('sql.js');
if(fs.existsSync('.env'))for(const l of fs.readFileSync('.env','utf8').split('\n')){const m=l.match(/^(\w+)=(.*)$/);if(m&&!process.env[m[1]])process.env[m[1]]=m[2]}
const PORT=process.env.PORT||3410,ADMIN=process.env.ADMIN_PASSWORD,API='https://api-demo.bybit.com';
if(process.env.VERCEL)process.env.TZ='Asia/Tokyo';let DATA_DIR=process.env.DATA_DIR||(process.env.VERCEL?'/tmp/data':'data');try{fs.mkdirSync(DATA_DIR+'/uploads',{recursive:true})}catch(e){console.error('DATA_DIR fallback',e.code);DATA_DIR='data';fs.mkdirSync(DATA_DIR+'/uploads',{recursive:true})}const DBF=DATA_DIR+'/app.db';if(!fs.existsSync(DBF)&&fs.existsSync(path.join(__dirname,'seed/app.db'))){fs.copyFileSync(path.join(__dirname,'seed/app.db'),DBF);for(const f of fs.readdirSync(path.join(__dirname,'seed/uploads')))fs.copyFileSync(path.join(__dirname,'seed/uploads',f),DATA_DIR+'/uploads/'+f)};let db;const save=()=>fs.writeFileSync(DBF,Buffer.from(db.export()));
const all=(q,p=[])=>{const s=db.prepare(q);s.bind(p);const r=[];while(s.step())r.push(s.getAsObject());s.free();return r};
const one=(q,p)=>all(q,p)[0];const run=(q,p=[])=>{db.run(q,p);save()};
const getS=k=>(one('SELECT v FROM settings WHERE k=?',[k])||{}).v||'';const setS=(k,v)=>run('INSERT OR REPLACE INTO settings(k,v) VALUES(?,?)',[k,v]);
const upload=multer({dest:DATA_DIR+'/uploads',limits:{fileSize:10e6}});const app=express();app.use(express.urlencoded({extended:true,limit:'2mb'}));app.use('/uploads',(q,s,n)=>authed(q)?n():s.sendStatus(403),express.static(DATA_DIR+'/uploads'));
const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const num=(n,f=2)=>Number(n).toLocaleString('ja-JP',{minimumFractionDigits:f,maximumFractionDigits:f});const u=(n,f=2)=>num(n,f)+' USDT';
const sg=n=>(n>=0?'+':'');const pct=n=>sg(n)+(n*100).toFixed(2)+'%';
const md=s=>{const d=new Date(s);return (d.getMonth()+1)+'/'+d.getDate()};const dd=(a,b)=>Math.round((new Date(b)-new Date(a))/864e5);
const jst=(ms=Date.now())=>new Date(ms+9*36e5).toISOString().slice(0,10);
const DEMO='<span class="demob">DEMO</span>';
// ===== 計算エンジン =====
// マスター日次リターン r_d = (E_d − 入出金_d − E_{d−1}) / E_{d−1}
function masterSeries(){const m=all('SELECT date,equity,flow FROM master ORDER BY date');const out=[];for(let i=0;i<m.length;i++){const p=m[i-1];out.push({...m[i],r:p?(m[i].equity-m[i].flow-p.equity)/p.equity:0})}return out}
// クライアント残高：開始日に軍資金 → 翌日以降 B=B×(1+r_d)+追加入金_d
function clientCalc(c,ms){ms=ms||masterSeries();const dep={};for(const d of all('SELECT date,amount FROM deposits WHERE client_id=?',[c.id]))dep[d.date]=(dep[d.date]||0)+d.amount;
 const s=ms.filter(x=>x.date>=c.start_date);let B=null,inv=0,idx=1,peak=1,mdd=0;const ser=[];
 for(const x of s){if(B===null){B=c.capital+(dep[x.date]||0);inv=B}else{B=B*(1+x.r);idx*=1+x.r;if(dep[x.date]){B+=dep[x.date];inv+=dep[x.date]}}peak=Math.max(peak,idx);mdd=Math.max(mdd,1-idx/peak);ser.push({date:x.date,balance:B,share:B/x.equity,inv,dep:ser.length?(dep[x.date]||0):0})}
 if(B===null)return {ser:[],bal:c.capital,inv:c.capital,pnl:0,rate:0,twr:0,mdd:0,day:0,asof:c.start_date,pending:true};
 const last=ser[ser.length-1];return {ser,bal:B,inv,pnl:B-inv,rate:(B-inv)/inv,twr:idx-1,mdd,day:dd(c.start_date,last.date)+1,asof:last.date};}
function clientTrades(k){const sh={};k.ser.forEach((x,i)=>{sh[x.date]=i?k.ser[i-1].share:null});
 return all('SELECT * FROM trades ORDER BY ts DESC').map(t=>({...t,d:jst(t.ts)})).filter(t=>sh[t.d]).map(t=>({...t,cp:t.pnl*sh[t.d],cq:t.qty*sh[t.d]}))}
