const addY=(d,n)=>{const x=new Date(d);x.setUTCFullYear(x.getUTCFullYear()+n);return x.toISOString().slice(0,10)};
const DEF_ACTS=[{t:'現在のポジション',b:'相場の上昇・下落の両面に対応し、安定的な利益の積み上げを目指します。'},{t:'運用方針',b:'超短期スキャルピング戦略で、1日に数回の取引を行います。短い時間での利益確定を繰り返します。'},{t:'リスク管理',b:'レバレッジ上限を厳守。損切りラインを事前に設定し、厳格な資金管理を徹底しています。'},{t:'次回のアクション',b:'市場の変動に応じて柔軟に対応し、安全性を最優先に運用を継続します。'}];
