app.get('/admin/master',(q,s)=>{const ms=masterSeries().reverse();const ev=all('SELECT * FROM evidence ORDER BY id DESC');const hasKey=!!getS('api_key');
 s.send(apage('共有口座',`<div class="ah"><h1>共有口座 <span class="dmb">DEMO</span></h1>${anav('/admin/master')}</div>${aflash(q)}<style>.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.grid2{display:grid;grid-template-columns:1.3fr 1fr;gap:16px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:18px;margin-bottom:16px}.card h2{font-size:15px;margin:0 0 12px}.form button,.card button{border:1px solid #2563eb;background:#2563eb;color:#fff;border-radius:8px;padding:7px 12px;cursor:pointer;font-family:inherit}.btn.ghost{background:#fff!important;color:#2563eb!important}.muted{color:#6b7280;font-size:12px}.g{color:#16a34a}.r{color:#dc2626}.thumb,.ev img{max-width:100%;max-height:160px;border-radius:8px}.ev{display:grid;grid-template-columns:1fr 1fr;gap:10px}.ev span{display:block;font-size:11px;color:#6b7280}</style><div class="grid3"><section class="card"><h2>① Bybitデモから自動取得</h2><p class="muted">毎日 0:05（日本時間）に残高・入出金・決済済み取引を取得して保存します（Bybitの取引履歴は7日分しか残らないため毎日保存）。</p><form method="post" action="/admin/master/fetch"><button ${hasKey?'':'disabled'}>今すぐ取得</button></form>${hasKey?'<p class="muted">APIキー：設定済み</p>':'<p class="r"><a href="/admin/settings">共有口座設定</a>でAPIキーを登録してください。</p>'}</section>
<section class="card"><h2>② 手入力</h2><form method="post" action="/admin/master/manual" class="form"><label>日付<input type="date" name="date" value="${jst()}"></label><label>口座残高（USDT）<input type="number" step="0.01" name="equity" required></label><label>当日の入出金（デモ資金追加など）<input type="number" step="0.01" name="flow" value="0"></label><button>登録</button></form></section>
<section class="card"><h2>③ スクショから読み取り</h2><form method="post" action="/admin/master/upload" enctype="multipart/form-data" class="form"><input type="file" name="img" accept="image/*" required><label>種類<select name="kind"><option value="資産">資産（お客様ページ1に最新を表示）</option><option>取引</option></select></label><label><input type="checkbox" name="public" value="1" checked style="width:auto"> お客様ページに表示</label><button>アップロード</button></form><p class="muted">残高を自動で読み取ります。確認後に登録してください。</p></section></div>
${ev.filter(e=>e.ocr_value&&!e.confirmed).map(e=>`<section class="card"><h2>読み取り結果の確認</h2><img src="/uploads/${e.file}" class="thumb"><form method="post" action="/admin/master/confirm/${e.id}" class="form"><label>残高（修正可）<input type="number" step="0.01" name="equity" value="${e.ocr_value}"></label><label>日付<input type="date" name="date" value="${jst()}"></label><label>当日の入出金<input type="number" step="0.01" name="flow" value="0"></label><button>この値で登録</button></form></section>`).join('')}
<div class="grid2"><section class="card"><h2>日次履歴（新しい順）</h2><table class="tbl"><tr><th>日付</th><th>口座残高</th><th>入出金</th><th>日次リターン</th><th>方法</th><th></th></tr>${ms.slice(0,60).map(x=>`<tr><td data-l="日付">${x.date}</td><td data-l="口座残高">${u(x.equity)}</td><td data-l="入出金">${x.flow?sg(x.flow)+num(x.flow,0):'—'}</td><td data-l="日次リターン" class="${x.r>=0?'g':'r'}">${pct(x.r)}</td><td data-l="方法">${esc(x.source||'')}</td><td><form method="post" action="/admin/master/del/${x.date}" onsubmit="return confirm('削除しますか？')"><button class="btn sm ghost">削除</button></form></td></tr>`).join('')}</table></section>
<section class="card"><h2>設定</h2><form method="post" action="/admin/master/settings" class="form"><p class="muted">APIキーは<a href="/admin/settings">共有口座設定</a>で登録します。</p><label>運用方針（全クライアント共通）<textarea name="strategy" rows="5">${esc(getS('strategy'))}</textarea></label><label>レバレッジ上限（倍）<input type="number" name="leverage" value="${esc(getS('leverage')||10)}"></label><label>ポジション<select name="position">${['ロング','ショート'].map(x=>`<option ${(getS('position')||'ロング')==x?'selected':''}>${x}</option>`).join('')}</select></label>${acts().map((a,i)=>`<label>アクション0${i+1} 見出し（運用進捗レポート）<input name="at${i}" value="${esc(a.t)}"></label><label>アクション0${i+1} 本文<textarea name="ab${i}" rows="2">${esc(a.b)}</textarea></label>`).join('')}<button>保存</button></form>
<h2 style="margin-top:18px">証跡画像（管理用）</h2><div class="ev">${ev.map(e=>`<div><img src="/uploads/${e.file}"><span>${e.kind}・${e.created}・${e.public?'公開中':'非公開'}</span><form method="post" action="/admin/master/pub/${e.id}"><button class="btn sm ghost">${e.public?'非公開にする':'公開する'}</button></form></div>`).join('')||'<p class="muted">なし</p>'}</div></section></div>`))});
